"""Codex forms of the nine agents and the manifest, generated by build-codex.py (single source: the .md files)."""
import json
import os
import shutil
import subprocess
import sys
import tempfile
import tomllib
import unittest
from pathlib import Path

from helpers import REPO

SCRIPT = REPO / 'l4-tools-guards' / 'scripts' / 'build-codex.py'


def run(*args, root=None, env=None):
    cmd = [sys.executable, str(SCRIPT), *args]
    if root:
        cmd += ['--root', str(root)]
    return subprocess.run(cmd, capture_output=True, text=True, env=env)


def copy_tree():
    tmp = Path(tempfile.mkdtemp())
    for sub in ('l2-design-judge/agents', 'l3-workers/agents', '.claude-plugin', 'codex', '.codex-plugin'):
        src = REPO / sub
        if src.is_dir():
            shutil.copytree(src, tmp / sub)
    return tmp


class CodexBuild(unittest.TestCase):
    def test_check_passes(self):
        r = run('--check')
        self.assertEqual(r.returncode, 0, r.stdout + r.stderr)

    def test_nine_unique_names(self):
        files = sorted((REPO / 'codex' / 'agents').glob('*.toml'))
        self.assertEqual(len(files), 9)
        names = [tomllib.loads(f.read_text())['name'] for f in files]
        self.assertEqual(len(set(names)), 9)
        for n in names:
            self.assertRegex(n, r'^my-agent-[a-z-]+$')

    def test_write_removes_stray_agent_file(self):
        tmp = copy_tree()
        try:
            stray = tmp / 'codex/agents/old.toml'
            stray.write_text('name = "old"\n')
            self.assertEqual(run('--check', root=tmp).returncode, 1)
            self.assertEqual(run('--write', root=tmp).returncode, 0)
            self.assertFalse(stray.exists())
            self.assertEqual(run('--check', root=tmp).returncode, 0)
            self.assertEqual(len(list((tmp / 'codex/agents').glob('*.toml'))), 9)
        finally:
            shutil.rmtree(tmp)

    def test_body_verbatim_and_no_unread_keys(self):
        src = (REPO / 'l3-workers/agents/coder.md').read_text()
        body = src.split('\n---\n', 1)[1]
        d = tomllib.loads((REPO / 'codex/agents/my-agent-coder.toml').read_text())
        self.assertEqual(d['developer_instructions'], body)
        self.assertEqual(set(d), {'name', 'description', 'developer_instructions'})

    def test_manifest_version(self):
        a = json.loads((REPO / '.claude-plugin/plugin.json').read_text())
        b = json.loads((REPO / '.codex-plugin/plugin.json').read_text())
        for k in ('name', 'version', 'description', 'author', 'hooks'):
            self.assertEqual(a[k], b[k])
        self.assertNotIn('skills', a)
        self.assertNotIn('skills', b)

    def test_changed_body_fails_check(self):
        tmp = copy_tree()
        try:
            p = tmp / 'l3-workers/agents/coder.md'
            p.write_text(p.read_text() + '\nextra line\n')
            r = run('--check', root=tmp)
            self.assertEqual(r.returncode, 1)
            self.assertIn('my-agent-coder.toml', r.stdout + r.stderr)
        finally:
            shutil.rmtree(tmp)

    def test_data_folder_agent_models_ignored(self):
        data = Path(tempfile.mkdtemp())
        try:
            (data / 'agent-models.json').write_text(json.dumps(
                {'presets': {'fast': {'coder': {'model': 'haiku', 'effort': 'low'}}}}))
            env = dict(os.environ, MA_TASKS_DIR=str(data), CLAUDE_PLUGIN_OPTION_DATA_DIR=str(data))
            tmp = copy_tree()
            try:
                r = run('--write', root=tmp, env=env)
                self.assertEqual(r.returncode, 0, r.stderr)
                for f in (REPO / 'codex' / 'agents').glob('*.toml'):
                    self.assertEqual((tmp / 'codex/agents' / f.name).read_text(), f.read_text())
                self.assertEqual((tmp / '.codex-plugin/plugin.json').read_text(),
                                 (REPO / '.codex-plugin/plugin.json').read_text())
            finally:
                shutil.rmtree(tmp)
        finally:
            shutil.rmtree(data)

    def test_no_home_path(self):
        for f in [*(REPO / 'codex' / 'agents').glob('*.toml'), REPO / '.codex-plugin/plugin.json']:
            self.assertNotIn('/Users/', f.read_text())


if __name__ == '__main__':
    unittest.main()
